.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-type-body);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ui-icon { display:inline-block; width:var(--p-icon-md); height:var(--p-icon-md); flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:var(--p-size-md-plus); color:var(--p-muted); }
.ds .ds-surface { border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:var(--p-blur-md); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }
.ds .ds-token-row { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-sm); }

.ds .ds-choices { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,var(--p-column-2xs)),1fr)); gap:var(--p-space-lg); }
.ds .ds-choices fieldset,.ds .ds-radio-group { border:0; padding:0; min-width:0; }
.ds .ds-choices legend,.ds .ds-radio-group legend { font-size:var(--p-text-body); font-weight:var(--p-weight-semibold); margin-bottom:var(--p-space-sm); padding:0; }
.ds .ds-choice { display:flex; align-items:center; gap:var(--p-space-sm); min-height:var(--p-control-size-sm); width:fit-content; padding-inline:var(--p-space-3xs); cursor:pointer; font-size:var(--p-text-body); }
.ds .ds-choice input { appearance:none; position:relative; margin:0; width:calc(var(--p-size-md-plus) + var(--p-size-4xs)); height:calc(var(--p-size-md-plus) + var(--p-size-4xs)); border:var(--p-border-width-strong) solid var(--p-control-border); border-radius:var(--p-radius-xs); background:var(--p-bg); box-shadow:var(--p-inset); cursor:inherit; flex-shrink:0; }
.ds .ds-choice input:checked,.ds .ds-choice input:indeterminate { background:var(--p-accent); border-color:var(--p-accent); box-shadow:none; }
.ds .ds-choice input[type="checkbox"]:checked::after { content:''; position:absolute; width:var(--p-size-2xs); height:var(--p-size-xs-plus); left:var(--p-space-2xs); top:var(--p-space-4xs); border:solid var(--p-on-accent); border-width:0 var(--p-border-width-strong) var(--p-border-width-strong) 0; transform:rotate(45deg); }
.ds .ds-choice input:indeterminate::after { content:''; position:absolute; width:var(--p-size-xs-plus); height:var(--p-size-4xs); left:var(--p-space-3xs); top:var(--p-space-xs); background:var(--p-on-accent); transform:none; border:0; }
.ds .ds-choice input[type="radio"] { border-radius:var(--p-radius-circle); }
.ds .ds-choice input[type="radio"]:checked::after { content:''; position:absolute; inset:var(--p-space-3xs); background:var(--p-on-accent); border-radius:var(--p-radius-circle); }
.ds .ds-choice:has(:disabled) { color:var(--p-muted); cursor:not-allowed; }
.ds .ds-choice input:disabled { opacity:var(--p-opacity-full); background:var(--p-disabled); border-color:var(--p-line); box-shadow:none; }
.ds .ds-choice input:disabled::after { border-color:var(--p-muted); }
.ds .ds-choice input[type="radio"]:disabled::after { background:var(--p-muted); }
.ds .ds-choice .ds-switch { width:var(--p-control-size-sm); height:calc(var(--p-size-lg) + var(--p-size-4xs)); border-radius:var(--p-radius-lg); }
.ds .ds-switch::before { content:''; position:absolute; top:var(--p-space-4xs); left:var(--p-space-4xs); width:calc(var(--p-size-md) + var(--p-size-4xs)); height:calc(var(--p-size-md) + var(--p-size-4xs)); border-radius:var(--p-radius-circle); background:var(--p-muted); box-shadow:var(--p-knob-shadow); transition:left var(--p-duration); }
.ds .ds-choice input.ds-switch:checked::after { content:none; }
.ds .ds-switch:checked::before { left:var(--p-space-md-plus); background:var(--p-on-accent); }
.ds .ds-switch:disabled::before { background:var(--p-muted); box-shadow:none; }
@media(forced-colors:active) {
  .ds .ds-choice input:not(.ds-switch) { appearance:auto; }
  .ds .ds-choice input:not(.ds-switch)::after { display:none; }
  .ds .ds-switch { border-color:ButtonText; }
  .ds .ds-switch::before { background:ButtonText; }
  .ds .ds-switch:checked { background:Highlight; }
  .ds .ds-switch:checked::before { background:HighlightText; }
}
/* looks: checkbox, radio and switch share the label hook .ds-choice[data-look]; checked keeps a mark or a moved thumb, never color alone */
.ds .ds-choice[data-look="card"] { min-width:var(--p-column-xs); min-height:var(--p-control-size-lg); padding:var(--p-space-sm) var(--p-space-md); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-control-radius); background:var(--p-bg); }
.ds .ds-choice[data-look="card"]:has(:checked) { border-color:var(--p-accent); box-shadow:inset 0 0 0 var(--p-border-width) var(--p-accent); background:var(--p-high); font-weight:var(--p-weight-semibold); }
.ds .ds-radio-group:has(> .ds-choice[data-look="card"]) .ds-choice + .ds-choice { margin-top:var(--p-space-xs); }
.ds .ds-choice[data-look="chip"] { gap:var(--p-space-2xs); min-height:var(--p-control-size-sm); padding:var(--p-space-xs) var(--p-space-md); border:var(--p-border-width) solid var(--p-control-border); border-radius:var(--p-radius-full); background:var(--p-bg); }
.ds .ds-choice[data-look="chip"] input { width:0; height:calc(var(--p-size-md) + var(--p-size-4xs)); border:0; background:transparent; box-shadow:none; }
.ds .ds-choice[data-look="chip"]:has(:focus-visible) { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ds-choice[data-look="chip"]:has(:checked) { padding-left:var(--p-space-sm); border-color:var(--p-accent); background:var(--p-accent); color:var(--p-on-accent); }
.ds .ds-choice[data-look="chip"] input:checked { width:calc(var(--p-size-md) + var(--p-size-4xs)); background:transparent; }
.ds .ds-choice[data-look="chip"] input[type="checkbox"]:checked::after { left:var(--p-space-2xs); top:var(--p-border-width); border-color:var(--p-on-accent); }
.ds .ds-choice[data-look="list"] { width:100%; flex-direction:row-reverse; justify-content:space-between; min-height:var(--p-control-size-md-plus); padding:var(--p-space-sm) var(--p-space-3xs); border-block:var(--p-border-width) solid var(--p-line); }
/* A settings list spans its container, so the whole row is the tap target. */
.ds .ds-radio-group:has(> .ds-choice[data-look="list"]) { width:100%; }
.ds .ds-radio-group:has(> .ds-choice[data-look="list"]) .ds-choice + .ds-choice { border-top:0; }
.ds .ds-radio-group:has(> .ds-choice[data-look="segment"]) { display:flex; flex-wrap:wrap; }
.ds .ds-radio-group:has(> .ds-choice[data-look="segment"]) > legend { width:100%; }
.ds .ds-choice[data-look="segment"] { position:relative; gap:var(--p-space-2xs); min-height:var(--p-control-size-sm); margin:0; padding:var(--p-space-xs-plus) calc(var(--p-space-md) + var(--p-space-4xs)); border:var(--p-border-width) solid var(--p-control-border); background:var(--p-bg); }
.ds .ds-choice[data-look="segment"] + .ds-choice[data-look="segment"] { margin-left:calc(var(--p-border-width) * -1); }
.ds .ds-choice[data-look="segment"]:first-of-type { border-radius:var(--p-radius-sm) 0 0 var(--p-radius-sm); }
.ds .ds-choice[data-look="segment"]:last-of-type { border-radius:0 var(--p-radius-sm) var(--p-radius-sm) 0; }
.ds .ds-choice[data-look="segment"] input { position:absolute; inset:0; width:100%; height:100%; opacity:0; }
.ds .ds-choice[data-look="segment"]:has(:checked) { z-index:var(--p-layer-raised); border-color:var(--p-accent); background:var(--p-accent); color:var(--p-on-accent); font-weight:var(--p-weight-semibold); }
.ds .ds-choice[data-look="segment"]:has(:checked)::before { content:'✓'; content:'✓' / ''; }
.ds .ds-choice[data-look="segment"]:has(:focus-visible) { z-index:var(--p-layer-lifted); outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset-tight); }
.ds .ds-choice[data-look]:has(:disabled) input:disabled { background:var(--p-disabled); border-color:var(--p-line); box-shadow:none; }
.ds .ds-choice[data-look]:has(:disabled) input:disabled::after { border-color:var(--p-muted); color:var(--p-muted); }
.ds .ds-choice[data-look]:has(:disabled) input:is([type="radio"],:indeterminate):disabled::after { background:var(--p-muted); }
.ds .ds-choice[data-look]:has(:disabled) input.ds-switch:disabled::before { background:var(--p-muted); box-shadow:none; }
.ds .ds-choice:is([data-look="chip"],[data-look="segment"],[data-look="card"]):has(:disabled) { border-color:var(--p-line); background:var(--p-disabled); color:var(--p-muted); box-shadow:none; }
/* all: one parent box above its children; the children sit indented so the tree reads without words */
.ds .ds-select-all { display:grid; gap:0; min-width:var(--p-column-md); margin:0; padding:0; border:0; }
.ds .ds-select-all > legend { padding:0 0 var(--p-space-xs); font-weight:var(--p-weight-semibold); font-size:var(--p-text-body); }
.ds .ds-select-all > .ds-choice { min-height:var(--p-control-size-sm); }
.ds .ds-select-all > .ds-choice:first-of-type { border-bottom:var(--p-border-width) solid var(--p-line); font-weight:var(--p-weight-semibold); }
.ds .ds-select-all > .ds-choice:not(:first-of-type) { padding-inline-start:var(--p-space-lg); }

(function mountParts(root) {
  root.querySelectorAll('[data-indeterminate]').forEach(input => {
    if (!input.__pattoveInitialized) { input.indeterminate = true; input.__pattoveInitialized = true; }
  });
  if (root.__pattovePartsMounted) return;
  root.__pattovePartsMounted = true;
  function selectTab(tab) {
    const tabs = tab.closest('.ds-tabs');
    tabs.querySelectorAll('[role="tab"]').forEach(item => {
      const active = item === tab;
      item.setAttribute('aria-selected', String(active)); item.tabIndex = active ? 0 : -1;
      tabs.querySelector('#' + CSS.escape(item.getAttribute('aria-controls'))).hidden = !active;
    });
    // A sideways-scrolling list brings the chosen tab fully into view.
    if (tabs.dataset.look === 'scroll') {
      const list = tab.parentElement;
      const pad = parseFloat(getComputedStyle(list).scrollPaddingLeft) || 0, lr = list.getBoundingClientRect(), tr = tab.getBoundingClientRect();
      if (tr.left - pad < lr.left) list.scrollLeft -= lr.left - tr.left + pad;
      else if (tr.right + pad > lr.right) list.scrollLeft += tr.right - lr.right + pad;
    }
    tabs.dispatchEvent(new CustomEvent('pattove:tabchange', { bubbles: true, detail: { label: tab.textContent.trim(), panel: tab.getAttribute('aria-controls') } }));
  }
  function filter(form) {
    const module = form.closest('.ds-search-module');
    const query = form.elements.query.value.trim().toLocaleLowerCase();
    // The picker look has no status menu, so it always searches every status.
    const status = form.elements.status?.value ?? 'all';
    let count = 0;
    module.querySelectorAll('[data-result]').forEach(item => {
      const match = query.split(/\s+/).every(term => item.dataset.result.toLocaleLowerCase().includes(term)) && (status === 'all' || item.dataset.resultStatus === status);
      item.hidden = !match; if (match) count++;
    });
    module.querySelector('.ds-result-count').textContent = count + '개의 컬렉션';
    module.querySelector('.ds-empty').hidden = count > 0;
    module.querySelector('.ds-demo-note').textContent = '';
  }
  root.addEventListener('submit', event => {
    if (!event.target.matches('[data-part-search]')) return;
    event.preventDefault(); filter(event.target);
  });
  // The picker look filters as the person types; the other looks wait for the search button.
  root.addEventListener('input', event => {
    if (event.target.matches('[data-part-search][data-live] [name="query"]')) filter(event.target.form);
  });
  root.addEventListener('change', event => {
    // The status filter is a select, or a radio chip group in the chips look.
    if (event.target.matches('[data-part-search] [name="status"]')) filter(event.target.form);
    // Select-all: the parent sets every child, and each child sets the parent to all, some, or none.
    const group = event.target.closest('.ds-select-all');
    if (group) {
      const parent = group.querySelector('[data-part="select-all"]');
      const kids = [...group.querySelectorAll('input[type="checkbox"]:not([data-part="select-all"])')];
      if (event.target === parent) kids.forEach(kid => { kid.checked = parent.checked; });
      const on = kids.filter(kid => kid.checked).length;
      parent.checked = on === kids.length; parent.indeterminate = on > 0 && on < kids.length;
    }
  });
  root.addEventListener('click', event => {
    const tab = event.target.closest('.ds-tab');
    if (tab) selectTab(tab);
    const button = event.target.closest('[data-part-action]');
    if (!button || button.disabled) return;
    const action = button.dataset.partAction;
    if (['open-record', 'close-record', 'save-record'].includes(action)) {
      const module = button.closest('.ds-search-module');
      const detail = module.querySelector('.ds-record-detail');
      if (action === 'save-record') {
        button.setAttribute('aria-pressed', String(button.getAttribute('aria-pressed') !== 'true'));
        module.__recordOpener.dataset.saved = button.getAttribute('aria-pressed');
        module.__recordOpener.setAttribute('aria-label', module.querySelector('.ds-record-detail h3').textContent + (button.getAttribute('aria-pressed') === 'true' ? ', 보관됨, 상세 열기' : ', 상세 열기'));
        module.querySelector('.ds-demo-note').textContent = button.getAttribute('aria-pressed') === 'true' ? '이 화면에서 컬렉션에 보관했어요.' : '보관을 해제했어요.';
        const record = module.__recordOpener.closest('[data-result]');
        module.dispatchEvent(new CustomEvent('pattove:save', { bubbles: true, detail: {
          id: record.dataset.recordId,
          title: detail.querySelector('h3').textContent,
          description: detail.querySelector('p').textContent,
          tag: record.dataset.resultStatus,
          saved: button.getAttribute('aria-pressed') === 'true'
        } }));
        return;
      }
      const open = action === 'open-record';
      if (open) {
        module.__recordOpener = button;
        const card = button.closest('.ds-card');
        detail.querySelector('h3').textContent = card.querySelector('h3').textContent;
        detail.querySelector('p').textContent = card.querySelector('.ds-card-body > p').textContent;
        detail.querySelector('[data-part-action="save-record"]').setAttribute('aria-pressed', button.dataset.saved || 'false');
      }
      module.querySelectorAll(':scope > form, :scope > .ds-result-count, :scope > .ds-results').forEach(element => { element.hidden = open; });
      detail.hidden = !open;
      module.querySelector('.ds-demo-note').textContent = '';
      if (open) detail.focus(); else module.__recordOpener?.focus();
    } else if (action === 'clear-input') {
      const input = button.closest('.ds-input-group').querySelector('input');
      input.value = ''; input.dispatchEvent(new Event('input', { bubbles: true })); input.focus();
    } else if (action === 'reveal') {
      const input = button.closest('.ds-input-group').querySelector('input');
      const shown = input.type === 'password';
      input.type = shown ? 'text' : 'password';
      button.textContent = shown ? '숨기기' : '보기';
      button.setAttribute('aria-label', button.getAttribute('aria-label').replace(/ (보기|숨기기)$/, shown ? ' 숨기기' : ' 보기'));
    } else if (action === 'step') {
      const input = button.closest('.ds-input-group').querySelector('input');
      input.value = String(Math.max(Number(input.min || 0), (Number(input.value) || 0) + Number(button.dataset.step)));
      input.dispatchEvent(new Event('input', { bubbles: true }));
    } else if (action === 'undo') {
      // Undo closes the notice and hands focus back to the action that raised it.
      const example = button.closest('.ds-feedback-example');
      example.querySelector('[data-part-feedback]').hidden = true;
      example.querySelector('[data-part-action="notify"]')?.focus();
      button.dispatchEvent(new CustomEvent('pattove:undo', { bubbles: true }));
    } else if (action === 'notify') {
      button.closest('.ds-feedback-example').querySelector('[data-part-feedback]').hidden = false;
    } else if (action === 'nav') {
      const items = [...button.closest('nav').querySelectorAll(':scope > [data-part-action="nav"]')];
      items.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
      button.dispatchEvent(new CustomEvent('pattove:navigate', { bubbles: true, detail: { index: items.indexOf(button), label: button.textContent.trim() } }));
    } else if (action === 'create') {
      button.dispatchEvent(new CustomEvent('pattove:create', { bubbles: true }));
    } else if (action === 'select-card') {
      const card = button.closest('.ds-card');
      const selected = card.dataset.selected !== 'true';
      card.dataset.selected = String(selected);
      button.setAttribute('aria-pressed', String(selected));
      button.lastChild.textContent = selected ? '선택됨' : '선택하기';
      card.dispatchEvent(new CustomEvent('pattove:select', { bubbles: true, detail: { selected, title: card.querySelector('h3').textContent } }));
    } else if (action === 'reset-search') {
      const form = button.closest('.ds-search-module').querySelector('form');
      form.reset(); filter(form); form.elements.query.focus();
    } else if (action === 'press') {
      button.dispatchEvent(new CustomEvent('pattove:action', { bubbles: true, detail: { label: button.getAttribute('aria-label') || button.textContent.trim() } }));
      const region = button.closest('.ds-search-module, .part-demo, .specimen') || root;
      const output = region.querySelector('.ds-demo-note');
      if (output) {
        const card = button.closest('.ds-card');
        output.textContent = card ? card.querySelector('h3').textContent + ' 선택됨' : (button.getAttribute('aria-label') || button.textContent.trim()) + ' 버튼을 눌렀어요.';
      }
    }
  });
  root.addEventListener('keydown', event => {
    const tab = event.target.closest('.ds-tab');
    if (!tab) return;
    const list = tab.closest('[role="tablist"]');
    // A vertical tab list moves with the up and down arrows, a horizontal one with left and right.
    const [back, forward] = list.getAttribute('aria-orientation') === 'vertical' ? ['ArrowUp', 'ArrowDown'] : ['ArrowLeft', 'ArrowRight'];
    if (![back, forward, 'Home', 'End'].includes(event.key)) return;
    event.preventDefault();
    const tabs = [...list.querySelectorAll('.ds-tab')];
    const current = tabs.indexOf(tab);
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (current + (event.key === forward ? 1 : -1) + tabs.length) % tabs.length;
    selectTab(tabs[next]); tabs[next].focus();
  });
})(document);

